$formMatch=[regex]::Match($hta,'(?is)<form\b[^>]*(?:id|name)\s*=\s*["'']frmMain["''][^>]*>(?<body>.*?)</form>');if(-not$formMatch.Success){throw 'frmMain missing.'}
$body=$formMatch.Groups['body'].Value;$offset=$formMatch.Groups['body'].Index;$scriptRanges=@([regex]::Matches($body,'(?is)<script\b.*?</script>'))
$controls=@();$ordinal=0
foreach($m in [regex]::Matches($body,'(?is)<(input|select|textarea|button)\b[^>]*>')){
    $inside=$false;foreach($range in $scriptRanges){if($m.Index-ge$range.Index-and$m.Index-lt($range.Index+$range.Length)){$inside=$true;break}};if($inside){continue}
    $ordinal++;$tag=$m.Value;$element=$m.Groups[1].Value.ToLowerInvariant();$kind=if($element-eq'input'){Get-Attr $tag 'type'}else{$element};if(-not$kind){$kind='text'}
    $controls+=[pscustomobject][ordered]@{ordinal=$ordinal;id=Get-Attr $tag 'id';name=Get-Attr $tag 'name';element=$element;control_kind=$kind.ToLowerInvariant();source_line=1+[regex]::Matches($hta.Substring(0,$offset+$m.Index),"`n").Count;value=Get-Attr $tag 'value';maxlength=Get-Attr $tag 'maxlength';disabled=$tag-match'(?i)\bdisabled(?:\s*=|\s|>)';readonly=$tag-match'(?i)\breadonly(?:\s*=|\s|>)'}
}
