$required=@('frm1604c:txtYear','frm1604c:tinA','frm1604c:tinB','frm1604c:tinC','frm1604c:branchCode','frm1604c:rdoCode','frm1604c:registeredName','frm1604c:registeredAddress','frm1604c:zipCode','frm1604c:categoryAgent_1','frm1604c:categoryAgent_2','frm1604c:telephoneNumber')
$computed='(?i)(TaxWheldTotal|AdjTotal|PenTotal|TotalAmt\d+|txtSched1Total)$'
function Meta([string]$Key,$Control){
    $page=if($Key-match'(?i)Sched1'){2}else{1};$item=$null;$logical='string';$status='optional';$enum=[object[]]@();$norm=[string[]]@()
    if($Key-match'(?i)txtSched1(?:Date|BankVal|Tra|TaxWheld|Adj|Pen|TotalAmt)(?<n>\d+)$'){$item="Part II row $($Matches.n)"}
    elseif($Key-match'(?i)^frm1604c:txt(?<n>12)$'){$item=$Matches.n}
    elseif($Key-match'(?i)^frm1604c:select(?<n>13)$'){$item=$Matches.n}
    if($Key-match'(?i)(amendedRtn|categoryAgent|topAgent|releasedOfFunds)'){$logical='boolean';$enum=[object[]]@('true','false')}
    elseif($Key-match'(?i)(tinA|tinB|tinC|branchCode|rdoCode)'){$logical='code'}
    elseif($Key-eq'txtEmail'){$logical='email-string'}
    elseif($Key-match'(?i)telephone'){$logical='phone-string'}
    elseif($Key-match'(?i)(Date\d+|txtRefMonth|txtRefDate|txtRefYear)'){$logical='date-component-or-string';$norm=[string[]]@('MM/DD/YYYY where assembled or checked')}
    elseif($Key-match'(?i)(TaxWheld|Adj|Pen|TotalAmt|txt12|Total$)'){$logical='decimal-amount';$norm=[string[]]@('NumWithComma','round(this,2)','formatCurrency')}
    elseif($Key-match'(?i)(txtYear|txtSheets)'){$logical='integer'}
    if($required-contains$Key){$status='required'};$isComputed=$Key-match$computed;if($isComputed){$status='computed'};if($Key-match'^(txtFinalFlag|txtEnroll|ebirOnline|driveSelectTPExport)'){$status='hidden'}
    $constraints=[ordered]@{};if($Control-and$Control.maxlength-and$Control.maxlength-match'^\d+$'){$constraints.max_length=[int]$Control.maxlength}
    [pscustomobject]@{page=$page;item=$item;logical=$logical;status=$status;enum=$enum;norm=$norm;computed=$isComputed;constraints=[pscustomobject]$constraints}
}
$labels=@{
    'frm1604c:txtYear'='Taxable year';'frm1604c:txtSheets'='Number of attached sheets';'frm1604c:rdoCode'='RDO code'
    'frm1604c:registeredName'='Withholding agent name';'frm1604c:registeredAddress'='Registered address';'frm1604c:zipCode'='ZIP code'
