    $label=if($labels.ContainsKey($key)){$labels[$key]}elseif($key-match'(?i)txtSched1(?<kind>Date|BankVal|Tra|TaxWheld|Adj|Pen|TotalAmt)(?<row>\d+)'){"Part II row $($Matches.row) $($Matches.kind)"}else{$key}
    $fields.Add([pscustomobject][ordered]@{field_key=$key;serialized_key=$key;serialized_occurrence=1;label=$label;page=$meta.page;item_number=$meta.item;control_kind=if($control){$control.control_kind}else{'runtime-injected-control'};storage_type='string';logical_type=$meta.logical;required=$meta.status;required_when=if($key-match'(?i)(txtRef|txt12|select13)'){'Item 11 Released of Funds is Yes.'}else{$null};enabled_when=if($key-match'(?i)(txtRef|txt12|select13)'){'frm1604c:releasedOfFunds_1 is checked.'}else{$null};visible_when=$null;default_value=if($control){$control.value}else{$null};empty_representation='';constraints=$meta.constraints;enum_values=$meta.enum;normalization=$meta.norm;computed=$meta.computed;calculation_id=if($meta.computed){'See calculations.json'}else{$null};source_refs=$refs;confidence=if($control){'high'}else{'medium'};notes=@('Observed in matching 119-key plaintext and decrypted encrypted dummy-save inventories; values are excluded.')})
}
