function Rule([string]$Id,[string]$Phase,$Order,[string]$Condition,[string[]]$FieldKeys,$Message,[string[]]$Refs,[string]$Assessment='verified-correct',[string]$Official='The branch alerts and returns.',[string]$Recommended='Retain as a structured revision-aware error.',[string]$Confidence='high'){
